def prefix_count_queries(words, queries):
    root = {}
    COUNT = "$count"
    for word in words:
        node = root
        for ch in word:
            node = node.setdefault(ch, {})
            node[COUNT] = node.get(COUNT, 0) + 1

    result = []
    for q in queries:
        if not q:
            result.append(len(words))
            continue
        node = root
        found = True
        for ch in q:
            if ch not in node:
                found = False
                break
            node = node[ch]
        result.append(node.get(COUNT, 0) if found else 0)
    return result
